def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def best_by_score(items, score_fn, default=None):
        best_item = default
        best_score = None
        for item in items or []:
            p = pos(item, None)
            if p is None:
                continue
            s = score_fn(p)
            if best_score is None or s < best_score:
                best_score = s
                best_item = p
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_p = (sx, sy)
    opp_p = (ox, oy)

    w = observation.get("grid_width", observation.get("width", 0)) or 0
    h = observation.get("grid_height", observation.get("height", 0)) or 0
    try:
        w = int(w)
        h = int(h)
    except Exception:
        w = h = 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)

        corners = []
        if w > 0 and h > 0:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = max(corners, key=lambda c: dist(c, opp_p))
        move = step_toward(self_p, target)
        if move == [0, 0]:
            move = step_away(self_p, opp_p)
        return move

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        best = best_by_score(targets, lambda p: dist(self_p, p))
        if best is not None:
            move = step_toward(self_p, best)
            if move != [0, 0]:
                return move
        # fallback: pressure opponent or hold position
        if dist(self_p, opp_p) <= 1:
            return step_away(self_p, opp_p)
        return step_toward(self_p, opp_p)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best_resource = best_by_score(resources, lambda p: dist(self_p, p))
    if best_resource is not None:
        # If opponent is clearly closer to that resource, pressure them instead.
        if dist(opp_p, best_resource) + 1 < dist(self_p, best_resource):
            return step_toward(self_p, opp_p)
        return step_toward(self_p, best_resource)

    # Generic fallback: either chase if close, otherwise drift toward opponent.
    if dist(self_p, opp_p) <= 2:
        return step_toward(self_p, opp_p)
    return step_away(self_p, opp_p)

